            diag_controlled_loosening_enabled = bool(AION_CONTROLLED_LOOSENING_ENABLED and AION_EXPECTANCY_SCORE_ENABLED)
            diag_expectancy_score_enabled = bool(AION_EXPECTANCY_SCORE_ENABLED)
